extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var save_manager := get_node_or_null("/root/SaveManager")
	if not check("save_mgr_exists", save_manager != null, "L'Autoload SaveManager deve essere registrato in /root/SaveManager"):
		return

	if not check("save_mgr_methods", has_function(save_manager, "save_game") and has_function(save_manager, "load_game") and has_function(save_manager, "unlock_level"), "SaveManager deve avere i metodi save_game(), load_game() e unlock_level()"):
		return

	save_manager.set("max_unlocked_level", 1)
	call_if_exists(save_manager, "save_game")
	call_if_exists(save_manager, "unlock_level", [2])
	var current_lvl = get_prop(save_manager, "max_unlocked_level", 0)
	check("unlock_lvl2", int(current_lvl) >= 2, "Chiamando unlock_level(2), max_unlocked_level deve diventare almeno 2 (è %s)" % str(current_lvl))

	save_manager.set("max_unlocked_level", 1)
	call_if_exists(save_manager, "load_game")
	var loaded_lvl = get_prop(save_manager, "max_unlocked_level", 0)
	check("load_persists", int(loaded_lvl) >= 2, "load_game() deve caricare il progresso salvato su disco (atteso >= 2, trovato %s)" % str(loaded_lvl))

	save_manager.set("max_unlocked_level", 1)
	call_if_exists(save_manager, "save_game")

	var menu := await instantiate_scene("res://ui/main_menu.tscn")
	if not check("menu_instantiate", menu != null, "La scena res://ui/main_menu.tscn deve istanziarsi senza errori"):
		return

	var btn_lvl1 := find_by_name(menu, "Level1Button") as Button
	var btn_lvl2 := find_by_name(menu, "Level2Button") as Button
	var btn_lvl3 := find_by_name(menu, "Level3Button") as Button

	if check("buttons_exist", btn_lvl1 != null and btn_lvl2 != null and btn_lvl3 != null, "Il menu deve contenere i pulsanti Level1Button, Level2Button e Level3Button"):
		check("btn1_enabled", not btn_lvl1.disabled, "Level1Button deve essere abilitato con livello 1 sbloccato")
		check("btn2_disabled", btn_lvl2.disabled, "Level2Button deve essere disabilitato quando max_unlocked_level è 1")
		check("btn3_disabled", btn_lvl3.disabled, "Level3Button deve essere disabilitato quando max_unlocked_level è 1")

	var player_scene := await instantiate_scene("res://player/player.tscn")
	if not check("player_scene", player_scene != null, "La scena res://player/player.tscn deve istanziarsi senza errori"):
		return

	var jump_audio := find_by_name(player_scene, "JumpAudio")
	var hit_audio := find_by_name(player_scene, "HitAudio")
	check("audio_nodes", jump_audio != null and hit_audio != null, "Il Player deve contenere i nodi JumpAudio e HitAudio")

	if jump_audio != null:
		var stream = get_prop(jump_audio, "stream")
		check("jump_stream", stream != null, "JumpAudio deve avere uno stream audio assegnato")

	if hit_audio != null:
		var stream = get_prop(hit_audio, "stream")
		check("hit_stream", stream != null, "HitAudio deve avere uno stream audio assegnato")

	if player_scene is CharacterBody2D:
		var body := player_scene as CharacterBody2D
		body.position = Vector2(200, 200)
		body.velocity = Vector2.ZERO
		await tap_action("jump")
		await wait_physics_frames(2)
		check("jump_action", body.velocity.y < 0.0, "Premendo jump il Player deve saltare con velocity.y negativa")

		if has_function(body, "die"):
			call_if_exists(body, "die")
			await wait_frames(2)
			check("die_runs", true, "La funzione die() deve eseguirsi senza errori")

	var goal_scene := await instantiate_scene("res://objects/goal.tscn")
	if check("goal_scene", goal_scene != null, "La scena res://objects/goal.tscn deve esistere"):
		check("goal_has_unlock", "unlocks_level" in goal_scene, "Il nodo Goal deve avere la proprietà esportata unlocks_level")

