enum State { IDLE, RUN, JUMP, FALL, DOUBLE_JUMP }

const SPEED := 160.0
const JUMP_VELOCITY := -360.0
const COYOTE_TIME := 0.15
const JUMP_BUFFER_TIME := 0.15

var state := State.IDLE
var gravity: float = ProjectSettings.get_setting("physics/2d/default_gravity", 980.0)

var coyote_timer := 0.0
var jump_buffer_timer := 0.0
var is_touching_wall := false
var has_double_jump := true
var respawn_point := Vector2.ZERO
var was_on_floor := false

@onready var sprite: Sprite2D = $Sprite2D
@onready var anim_player: AnimationPlayer = $AnimationPlayer
@onready var hurtbox: Area2D = $Hurtbox
@onready var jump_audio: AudioStreamPlayer2D = $JumpAudio
@onready var hit_audio: AudioStreamPlayer2D = $HitAudio


func _ready() -> void:
	add_to_group("player")
	respawn_point = global_position
	if hurtbox != null:
		hurtbox.area_entered.connect(_on_hurtbox_area_entered)
		hurtbox.body_entered.connect(_on_hurtbox_body_entered)


func _physics_process(delta: float) -> void:
	if not is_on_floor():
		velocity.y += gravity * delta
		coyote_timer -= delta
	else:
		coyote_timer = COYOTE_TIME
		has_double_jump = true
		if not was_on_floor:
			_squash_and_stretch(Vector2(1.2, 0.8))

	was_on_floor = is_on_floor()

	if Input.is_action_just_pressed("jump"):
		jump_buffer_timer = JUMP_BUFFER_TIME
	else:
		jump_buffer_timer -= delta

	if jump_buffer_timer > 0.0 and coyote_timer > 0.0:
		_perform_jump()
		jump_buffer_timer = 0.0
		coyote_timer = 0.0
	elif Input.is_action_just_pressed("jump") and not is_on_floor() and has_double_jump:
		_perform_jump()
		has_double_jump = false

	var direction := Input.get_axis("move_left", "move_right")
	if direction != 0.0:
		velocity.x = direction * SPEED
		if sprite != null:
			sprite.flip_h = (direction < 0.0)
	else:
		velocity.x = move_toward(velocity.x, 0.0, SPEED)

	move_and_slide()
	is_touching_wall = is_on_wall()
	_update_state()


func _perform_jump() -> void:
	velocity.y = JUMP_VELOCITY
	_squash_and_stretch(Vector2(0.8, 1.2))
	if jump_audio != null:
		jump_audio.pitch_scale = randf_range(0.95, 1.05)
		jump_audio.play()


func _squash_and_stretch(target_scale: Vector2) -> void:
	if sprite == null:
		return
	var tween := create_tween()
	tween.tween_property(sprite, "scale", target_scale, 0.06)
	tween.tween_property(sprite, "scale", Vector2.ONE, 0.08)


func _update_state() -> void:
	if is_on_floor():
		if absf(velocity.x) > 10.0:
			state = State.RUN
		else:
			state = State.IDLE
	else:
		if velocity.y < 0.0:
			state = State.JUMP
		else:
			state = State.FALL

	_update_animation()


func _update_animation() -> void:
	if anim_player == null:
		return

	match state:
		State.IDLE:
			anim_player.play("idle")
		State.RUN:
			anim_player.play("run")
		State.JUMP, State.DOUBLE_JUMP:
			anim_player.play("jump")
		State.FALL:
			anim_player.play("fall")


func die() -> void:
	if hit_audio != null:
		hit_audio.play()
	respawn()


func respawn() -> void:
	velocity = Vector2.ZERO
	global_position = respawn_point


func _on_hurtbox_area_entered(area: Area2D) -> void:
	if area.is_in_group("hazards") or area.is_in_group("enemies"):
		die()
	elif area.is_in_group("checkpoints"):
		respawn_point = area.global_position


func _on_hurtbox_body_entered(body: Node2D) -> void:
	if body.is_in_group("hazards") or body.is_in_group("enemies"):
		die()

